167:function render(){clearInterval(state.interval);if(state.phase==='setup')renderSetup();else if(state.phase==='deal')renderDeal();else if(state.phase==='clues')renderClues();else if(state.phase==='discussion')renderDiscussion();else if(state.phase==='startingPlayer')renderStartingPlayer();else if(state.phase==='verbalDiscussion')renderVerbalDiscussion();else if(state.phase==='vote')renderVote();else if(state.phase==='roundResult')renderRoundResult();else if(state.phase==='result')renderResult();else if(state.phase==='stats')renderStats()}
