46: function wordsFor(category){return(WORDS[category]||'').split(',').map(word=>word.trim()).filter(Boolean)}
47: function chooseWord(categories,usedWords){
48:  const pick=()=>{
49:   const available=categories.map(category=>({category,words:[...new Set(wordsFor(category))].filter(word=>!usedWords.includes(word))})).filter(group=>group.words.length);
50:   if(!available.length)return null;
51:   const group=available[Math.floor(Math.random()*available.length)];
52:   return{word:group.words[Math.floor(Math.random()*group.words.length)],category:group.category};
53:  };
54:  let selection=pick();if(!selection){usedWords.length=0;selection=pick()}return selection;
55: }
