node <<'NODE'
const fs=require('fs'),vm=require('vm');
const src=fs.readFileSync('app.js','utf8');
const end=src.indexOf('function render()');
const ctx={};vm.createContext(ctx);vm.runInContext(src.slice(0,end),ctx);
const {WORDS,generateHint,hintContainsSecret}=ctx;
let total=0, fallback=0, unsafe=0, blank=0;
for(const [category,list] of Object.entries(WORDS)) for(const word of list.split(',').map(s=>s.trim()).filter(Boolean)){
 const hint=generateHint(word,category); total++;
 if(!hint||!hint.trim())blank++;
 if(hintContainsSecret(hint,word))unsafe++;
 // A generated hint from a fallback is not directly observable; inspect rule group membership.
 const key=word.toLowerCase(); const matched=ctx.HINT_RULES[category]?.groups.some(g=>g.words.split('|').includes(key)); if(!matched)fallback++;
}
console.log({categories:Object.keys(WORDS).length,total,fallback,blank,unsafe});
for(const word of ['South Korea','Reykjavík','E.T.','Up','Key','Taylor Swift']) console.log(word,hintContainsSecret('A clue for '+word,word));
NODE

