171: function hintContainsSecret(hint,word){
172:  const tokens=value=>String(value).normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase().split(/[^a-z0-9]+/).filter(Boolean);
173:  const secret=tokens(word),clue=tokens(hint);
174:  if(!secret.length)return false;
175:  return clue.some((_,start)=>secret.every((token,index)=>clue[start+index]===token));
176: }
177: function hintHash(word,category){
178:  let hash=2166136261;
179:  for(const char of `${category}:${word}`){hash^=char.codePointAt(0);hash=Math.imul(hash,16777619)}
180:  return hash>>>0;
181: }
182: function generateHint(word,category){
183:  const rules=HINT_RULES[category];
184:  const key=String(word||'').trim().toLowerCase();
185:  const group=rules?.groups.find(rule=>rule.words.split('|').includes(key));
186:  const dedicated=group?.hints||[];
187:  const fallback=CATEGORY_HINT_FALLBACKS[category]||rules?.fallback||['Think about the setting, purpose, or defining features associated with this kind of thing.'];
188:  const choices=dedicated.filter(hint=>hint&& !hintContainsSecret(hint,word));
189:  const safeChoices=choices.length?choices:fallback.filter(hint=>hint&& !hintContainsSecret(hint,word));
190:  if(!safeChoices.length){
191:   const emergency=['Its context and defining traits may help.','Consider its role and usual setting.','Look at the features, skills, or surroundings involved.','Think about how it is used or experienced.','Its setting and purpose offer a useful starting point.'].filter(hint=>!hintContainsSecret(hint,word));
192:   if(emergency.length)return emergency[hintHash(key,category)%emergency.length];
193:   return ['Look closer.','Explore further.','Consider the context.'].find(hint=>!hintContainsSecret(hint,word))||'Look closer.';
194:  }
195:  return safeChoices[hintHash(key,category)%safeChoices.length];
196: }
