rty.stats[name]||{played:0,wins:0,points:party.scores[name]||0};return`<button class="stats-row" data-stat-player="${esc(name)}"><span class="stats-rank">${i+1}</span><strong>${esc(name)}</strong><span>${s.played} games · ${s.wins} wins</span><b>${s.points} pts</b></button>`}).join(''):'<p class="empty-note">Play a completed match to start your party record.</p>'}</div>`}<div class="history-heading"><h3>MATCH HISTORY</h3><span>${history.length} COMPLETED</span></div><div class="history-list">${history.length?history.slice(0,30).map(m=>`<div class="history-row"><div><strong>${esc(m.word||'—')}</strong><small>${new Date(m.date).toLocaleDateString()} · ${m.players.length} players</small></div><span class="history-winner ${m.winner==='imposters'?'imposter':''}">${m.winner==='imposters'?'IMPOSTER WIN':'ROOM WIN'}</span><small>${m.imposters.map(esc).join(', ')}</small></div>`).join(''):'<p class="empty-note">No completed matches yet.</p>'}</div><div class="stats-footer"><button id="resetStats" class="text-btn danger-text">Reset party stats & history</button></div></section></div>`;document.querySelector('#backStats').onclick=()=>{state.phase='setup';state.selectedStatPlayer=null;render()};document.querySelectorAll('[data-stat-player]').forEach(b=>b.onclick=()=>{state.selectedStatPlayer=b.dataset.statPlayer;render()});document.querySelector('#clearPlayer')?.addEventListener('click',()=>{state.selectedStatPlayer=null;render()});document.querySelector('#resetStats').onclick=()=>{if(!window.confirm(`Reset all scores, stats, and match history for “${party.name}”? This cannot be undone.`))return;party.scores={};party.stats={};party.history=[];state.scores=party.scores;state.selectedStatPlayer=null;save();render();toast('Party stats and history reset.')}}
  document.querySelector('#soundToggle').onclick=()=>{state.sound=!state.sound;document.querySelector('#soundToggle').classList.toggle('muted',!state.sound);document.querySelector('#soundToggle').textContent=state.sound?'♫':'♪'};
