const fs = require('fs');
const vm = require('vm');
const source = fs.readFileSync('app.js', 'utf8');
const start = source.indexOf('const WORDS');
const end = source.indexOf('function render()');
if (start < 0 || end < 0) throw new Error('Could not locate hint definitions');
const test = `${source.slice(start, end)}\nJSON.stringify(Object.entries(WORDS).flatMap(([category, raw]) => raw.split(',').map(word => [word.trim(), category])).map(([word, category]) => ({word, category, hint: generateHint(word, category), stable: generateHint(word, category) === generateHint(word, category), reveals: hintContainsSecret(generateHint(word, category), word)})))`;
const cases = JSON.parse(vm.runInNewContext(test));
const missing = cases.filter(x => !x.hint || !x.hint.trim());
const revealing = cases.filter(x => x.reveals);
const unstable = cases.filter(x => !x.stable);
const generic = cases.filter(x => /^(think about it|consider the context|look closer|explore further)\.?$/i.test(x.hint.trim()));
const offAssignment = /state\.hint=state\.settings\.hints\?generateHint\(state\.word,state\.wordCategory\):''/.test(source);
const roleReuse = /HINT: \$\{esc\(state\.hint\)\}/.test(source);
const offDisplay = /state\.settings\.hints\?`HINT: \$\{esc\(state\.hint\)\}`:'BLEND IN\. YOU DO NOT KNOW THE WORD\.'/s.test(source);
console.log(JSON.stringify({wordCount: cases.length, missing: missing.length, reveals: revealing.length, unstable: unstable.length, generic: generic.length, hintsOffEmpty: offAssignment, sameMatchHintReused: roleReuse, offRoleMessage: offDisplay}, null, 2));
if (missing.length || revealing.length || unstable.length || generic.length || !offAssignment || !roleReuse || !offDisplay) process.exit(1);
