245: const selection=chooseWord(state.settings.categories,state.usedWords);if(!selection){toast('No words available. Choose another category.');return}state.word=selection.word;state.usedWords.push(state.word);state.wordCategory=selection.category||'Uncategorized';state.hint=state.settings.hints?generateHint(state.word,state.wordCategory):'';state.matchId=`match-${Date.now()}-${Math.random().toString(36).slice(2,8)}`;state.startingPlayer='';state.previousStartingPlayer='';state.verbalStarted=false;const imposters=randomize([...state.players]).slice(0,state.settings.imposters);state.roles=state.players.map(name=>({name,imposter:imposters.includes(name)}));state.clues=[];state.votes={};state.voteRounds=[];state.eliminated=[];state.selectedVote=null;state.voteIndex=0;state.roleIndex=0;state.revealed=false;state.phase='deal';render()}
