255: function renderClues(){const roles=activeRoles(),p=roles[state.clueIndex];const done=state.clueIndex>=roles.length;app.innerHTML=`<div class="phase-wrap"><div class="phase-head"><div class="eyebrow">ROUND ${state.round} <span>·</span> CLUE ROUND</div><span class="round-tag">${Math.min(state.clueIndex+1,roles.length)} OF ${roles.length}</span></div><section class="panel clue-card"><div class="clue-top"><h2 class="settings-title">One clue. Keep it clever.</h2><span class="pill-info">NO SAYING THE WORD</span></div>${done?`<div class="center"><p class="phase-description">All clues are in. Talk it out, then cast your votes.</p><div class="clue-feed">${state.clues.map(c=>`<div class="clue-item"><span>${esc(c.name)}</span><strong>${esc(c.clue)}</strong></div>`).join('')}</div><button id="beginDiscussion" class="primary-btn" style="max-width:320px">${state.settings.timer?'START DISCUSSION TIMER':'GO TO VOTING'} &nbsp;→</button></div>`:`<div class="current-turn"><span class="avatar">${esc(p.name.charAt(0).toUpperCase())}</span><div><strong>${esc(p.name)}’s turn</strong><small>Pass the phone privately</small></div></div><div class="clue-entry"><input id="clueInput" class="text-input" maxlength="35" autocomplete="off" placeholder="Type a one-word clue…"><button id="submitClue" class="add-btn">Give clue →</button></div><div class="clue-feed">${state.clues.map(c=>`<div class="clue-item"><span>${esc(c.name)}</span><strong>${esc(c.clue)}</strong></div>`).join('')}</div>`}</section><div class="setup-footnote">HINTS, NOT DEFINITIONS. GIVE THEM SOMETHING TO DISCUSS.</div></div>`;
