3: /* Shared interaction and layout polish */
4: :focus-visible{outline:3px solid #9fc24d;outline-offset:3px}
5: button:disabled{opacity:.52;cursor:not-allowed;transform:none!important}
6: .primary-btn:disabled:hover{background:var(--green);color:var(--green-dark)}
7: .panel{min-width:0}
8: .phase-card h1 em,.stats-wrap .phase-head h1 em{font-style:normal;color:#98bd4b}
9: .party-bar{display:flex;align-items:end;gap:12px;padding:13px 15px;margin:-8px 0 17px;border:1px solid var(--line);border-radius:12px;background:#fffefa;box-shadow:var(--shadow)}
10: .party-bar>div{min-width:0;flex:1}
11: .party-bar .eyebrow{display:block;margin:0 0 5px 2px;font-size:9px}
12: .party-select{display:block;width:100%;height:39px;padding:0 35px 0 11px;border:1px solid var(--line);border-radius:8px;background:#fffefa;color:var(--ink);font-size:12px;font-weight:600;outline:none}
13: .party-select:focus{border-color:#9ab95b;box-shadow:0 0 0 3px #a8cc6026}
14: .party-bar .secondary-btn{height:39px;white-space:nowrap;padding:0 13px;font-size:10px}
15: .party-bar .mini-link{height:39px;white-space:nowrap;padding:0 8px}
16: .stats-panel{padding:clamp(18px,3vw,30px)}
17: .stats-wrap .phase-head h1{font:600 clamp(28px,4vw,40px)/1.1 'Space Grotesk',sans-serif;letter-spacing:-1.6px;margin:7px 0 0;overflow-wrap:anywhere}
18: .stats-toolbar{display:flex;align-items:center;justify-content:space-between;gap:15px;padding-bottom:19px;border-bottom:1px solid #f0eee9}
19: .stats-toolbar .phase-description{margin:5px 0 0;text-align:left}
20: .stats-toolbar .secondary-btn{height:40px;padding:0 13px;white-space:nowrap;font-size:10px}
21: .party-summary{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;padding:20px 0}
22: .party-summary>div,.stats-metrics>div{min-width:0;padding:15px 10px;border:1px solid #eeece6;border-radius:10px;background:#fbfaf6;text-align:center}
23: .party-summary strong,.stats-metrics strong{display:block;font:600 24px/1 'Space Grotesk',sans-serif;color:#36452b}
24: .party-summary span,.stats-metrics span{display:block;margin-top:8px;color:#8b9086;font:9px 'DM Mono',monospace;letter-spacing:.7px}
25: .stats-list{display:grid;gap:7px}
26: .stats-row{width:100%;min-width:0;display:grid;grid-template-columns:30px minmax(70px,1fr) minmax(110px,auto) auto;align-items:center;gap:10px;padding:11px 12px;border:1px solid #eeece6;border-radius:9px;background:#fffefa;color:var(--ink);text-align:left}
27: .stats-row:hover{border-color:#c5d89d;background:#f8faF3}
28: .stats-row strong{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:12px}
29: .stats-row>span:not(.stats-rank){color:#858a80;font-size:11px}
30: .stats-row b{font:500 11px 'DM Mono',monospace;color:#596d39;white-space:nowrap}
31: .stats-rank{height:26px;width:26px;display:grid;place-items:center;border-radius:8px;background:#f1f7e7;color:#6b8440;font:500 11px 'DM Mono',monospace}
32: .stats-metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:9px;padding:20px 0 10px}
33: .history-heading{display:flex;justify-content:space-between;align-items:center;margin-top:20px;padding:14px 0 9px;border-top:1px solid #f0eee9}
34: .history-heading h3{margin:0;font:600 12px 'Space Grotesk',sans-serif}
35: .history-heading span{color:#92968b;font:9px 'DM Mono',monospace;letter-spacing:.7px}
36: .history-list{display:grid;gap:7px}
37: .history-row{display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:center;gap:5px 12px;padding:11px 12px;border:1px solid #eeece6;border-radius:9px;background:#fffefa}
38: .history-row>div{min-width:0}
39: .history-row strong{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:12px}
40: .history-row small{display:block;margin-top:4px;color:#92968b;font-size:10px}
41: .history-row>small{grid-column:1/-1;margin:0}
42: .history-winner{padding:6px 8px;border-radius:99px;background:#f1f8e6;color:#627d35;font:9px 'DM Mono',monospace;white-space:nowrap}
43: .history-winner.imposter{background:#fff0eb;color:#bd654f}
44: .stats-footer{display:flex;justify-content:flex-end;margin-top:12px;border-top:1px solid #f0eee9;padding-top:10px}
45: .danger-text{color:#bd654f}
46: .category-label{margin-top:17px;font:500 9px 'DM Mono',monospace;letter-spacing:1.8px;color:#92968b}
47: .category-value{margin-top:4px;color:#788f48;font:600 13px 'DM Mono',monospace;letter-spacing:1.2px}
48: .starting-player-card{max-width:680px;margin:0 auto}
49: .starting-player-card>.eyebrow{color:#8b9b66}
50: .starting-player-name{color:#252e23}
51: .starting-player-name em{font-style:normal;color:#98bd4b}
52: .verbal-instruction{max-width:440px;margin:0 auto 13px;padding:15px 18px;border:1px solid #e8eddd;border-radius:10px;background:#f7faef;color:#68715e;font-size:13px;line-height:1.6}
53: .verbal-instruction strong{color:#3f4e2d}
54: .verbal-status{margin:0 auto 20px;color:#969a91;font-size:11px}
55: .start-discussion-row{margin-top:21px}
56: .start-discussion-row .primary-btn{max-width:330px}
57: .starting-player-card .timer{margin:27px 0;color:#242b24}
58: .starting-player-card .timer.urgent{color:var(--red)}
59: .starting-player-card .action-row{margin-top:20px}
60: .starting-player-card .action-row .primary-btn{max-width:330px}
