62: @media(max-width:900px){
63:   .app-shell{padding-right:28px;padding-left:28px}
64:   .setup-grid{grid-template-columns:minmax(0,1fr)}
65:   .settings-panel{order:1}
66:   .players-panel{order:0}
67:   .player-list{max-height:300px}
68: }
69: @media(max-width:650px){
70:   .app-shell{padding-right:17px;padding-left:17px}
71:   main{padding-top:22px}
72:   .party-bar{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:8px;margin:-4px 0 15px;padding:11px}
73:   .party-bar>div{grid-column:1/-1}
74:   .party-bar .secondary-btn{grid-column:1;grid-row:2}
75:   .party-bar .mini-link{grid-column:2;grid-row:2}
76:   .stats-toolbar{align-items:flex-start}
77:   .stats-toolbar .secondary-btn{max-width:125px;white-space:normal;line-height:1.25}
78:   .stats-row{grid-template-columns:27px minmax(0,1fr) auto;gap:8px;padding:10px}
79:   .stats-row>span:not(.stats-rank){grid-column:2;grid-row:2;font-size:10px}
80:   .stats-row b{grid-column:3;grid-row:1/3}
81:   .party-summary{gap:6px;padding:15px 0}
82:   .party-summary>div,.stats-metrics>div{padding:12px 5px}
83:   .party-summary strong,.stats-metrics strong{font-size:21px}
84:   .party-summary span,.stats-metrics span{font-size:8px;letter-spacing:.2px;line-height:1.4}
85:   .stats-metrics{gap:6px}
86:   .history-row{grid-template-columns:minmax(0,1fr) auto;gap:5px 7px;padding:10px}
87:   .history-winner{font-size:8px;padding:6px}
88:   .verbal-instruction{padding:13px 14px}
89:   .starting-player-card .phase-description{margin-bottom:20px}
90:   footer{gap:12px}
91:   footer span:last-child{text-align:right}
92: }
93: @media(max-width:390px){
94:   .app-shell{padding-right:12px;padding-left:12px}
95:   .party-bar{grid-template-columns:minmax(0,1fr);}
96:   .party-bar>div,.party-bar .secondary-btn,.party-bar .mini-link{grid-column:1;grid-row:auto}
97:   .party-bar .secondary-btn,.party-bar .mini-link{width:100%}
98:   .stats-toolbar{display:grid}
99:   .stats-toolbar .secondary-btn{max-width:none;width:100%}
100:   .party-summary strong,.stats-metrics strong{font-size:18px}
