on></div><div class="setup-footnote">NORMAL PLAYER WIN: +1 EACH · IMPOSTER WIN: +2 EACH</div></section></div>`;document.querySelector('#nextRound').onclick=()=>{state.round++;state.phase='setup';startGame()};document.querySelector('#backSetup').onclick=()=>{state.phase='setup';state.round=1;state.usedWords=[];render()}}
