app.js:259:function renderGuess(){const imposters=state.result.caught;app.innerHTML=`<div class="phase-wrap"><div class="phase-head"><div class="eyebrow">ONE LAST CHANCE</div><span class="round-tag">IMPOSTER GUESS</span></div><section class="panel phase-card"><div class="step-count">${imposters.map(n=>esc(n.toUpperCase())).join(' & ')}</div><h1>You’ve been found.<br><em>But do you know?</em></h1><p class="phase-description">The room got you. Guess the secret word correctly and steal the win for the imposter team.</p><form id="guessForm" class="clue-entry" style="max-width:400px;margin:0 auto"><input id="guessInput" class="text-input" maxlength="50" autocomplete="off" placeholder="Your final guess…"><button class="add-btn" type="submit">GUESS</button></form></section><div class="setup-footnote">ONE GUESS FOR THE IMPOSTER TEAM. TALK IT OVER.</div></div>`;document.querySelector('#guessForm').onsubmit=e=>{e.preventDefault();const guess=document.querySelector('#guessInput').value.trim();if(!guess){toast('Enter your guess first.');return}finishGame(guess.toLowerCase()===state.word.toLowerCase()?'imposters':'players',guess)}}

